node -e 'const fs=require("fs"),path=require("path")
const fail=(m)=>{console.error(m);process.exit(1)}
const re=/\bfocus(?:-within)?:(?:border|ring)-primary\b/
const norm=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ")
const hits=[];let n=0
const walk=(d)=>{for(const e of fs.readdirSync(d,{withFileTypes:true})){if(e.name==="node_modules"||e.name.startsWith("."))continue;const p=path.join(d,e.name);if(e.isDirectory())walk(p);else if(/\.tsx?$/.test(e.name)&&!/\.test\.tsx?$/.test(e.name)){n++;if(re.test(norm(fs.readFileSync(p,"utf8"))))hits.push(p)}}}
for(const r of ["app","components","lib"]){if(!fs.existsSync(r))process.exit(79);walk(r)}
if(n<500)process.exit(79)
if(hits.length)fail(hits.length+" files still focus a field with the brand orange (S8, LIVE-657): "+hits.slice(0,6).join(", "))
let f;try{f=norm(fs.readFileSync("components/ui/field.tsx","utf8"))}catch(e){process.exit(79)}
if(!/focus:border-border-strong/.test(f)||!/focus:ring-border-strong\/30/.test(f))fail("the field primitive no longer carries the neutral focus halo the owner ruled in (S8)")
console.log("ok: "+n+" files, no orange field focus")'
